principle.bad_example:
function handle(type: string, payload: unknown) {
  if (type === 'a') return processA(payload);
  else if (type === 'b') return processB(payload);
  else if (type === 'c') return processC(payload);
}

principle.good_example:
const HANDLERS: Record<Kind, Handler> = {
  a: processA,
  b: processB,
  c: processC,
};
function handle(kind: Kind, payload: Payload) {
  return HANDLERS[kind](payload);
}
